#include <vector>
#include <algorithm>
#include <omp.h>

/* Return the sum of the minimum value at each index of vectors x and y for all indices.
   i.e. sum = min(x_0, y_0) + min(x_1, y_1) + min(x_2, y_2) + ...
   The computation is performed in parallel with OpenMP and is correct for any
   number of threads.
*/
double sumOfMinimumElements(const std::vector<double>& x,
                            const std::vector<double>& y)
{
    // Use the smaller size if the vectors differ in length.
    const std::size_t n = std::min(x.size(), y.size());

    double sum = 0.0;

    #pragma omp parallel for reduction(+:sum)
    for (std::size_t i = 0; i < n; ++i) {
        sum += std::min(x[i], y[i]);
    }

    return sum;
}
